# cook your dish here
import sys

sys.setrecursionlimit(300000)
def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return 
    
    
    
    t = int(input_data[0])
    
    idx = 1
    
    out = []
    
    for _ in range(t):
        
        n = int(input_data[idx])
        a_arr = [int(x) for x in input_data[idx +1 : idx +1+3*n]]
        idx +=1+3*n
        a_arr.sort(reverse= True)
        
        S =[0] *(3*n+1)
        for i in range(3*n):
            S[i+1] = S[i] + a_arr[i]
            
            
        yxz = 0
        
        def get_val(a, b):
            return 2*S[a] + S[a +2*b]+ 3*S[3*n-2*a-b]
            
            
        max_t = 0
        
        
        for a in range(n+1):
            low = 0
            high  = n-a
            
            while high -low > 2:
                mid1 = low +(high - low) // 3
                mid2 = high - (high - low) // 3 
                if get_val(a, mid1) < get_val(a, mid2):
                    low = mid1
                    
                else:
                    high  = mid2
                    
                    
            for b in range(low, high+1):
                yxz = get_val(a,b)
                
                if yxz > max_t:
                    max_t = yxz




        out.append(str(max_t))
    sys.stdout.write("\n".join(out) + "\n")


if __name__ =="__main__":
    solve()
